                                   for j in range(3)) for i in range(3))
                shapes[mask] = color

    out = [row[:w//2] for row in grid]
    # The left panels are separated by complete rows of the background color.
    for r0 in range(1, h, 4):
        if r0 + 2 >= h:
            continue
        mask = tuple(tuple(int(grid[r0+i][j] == 0) for j in range(1, 4))
                     for i in range(3))
        color = shapes.get(mask)
        if color is not None:
            for i in range(3):
                for j in range(3):
                    if mask[i][j]:
                        out[r0+i][j+1] = color
