def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    left_w = w // 2
    out = [row[:left_w] for row in grid]

    # Record each colored object's shape within its bounding box.
    objects = {}
    seen = set()
    for r in range(h):
        for c in range(left_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and left_w <= nc < w and
                            grid[nr][nc] == color and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0, r1 = min(x for x, _ in cells), max(x for x, _ in cells)
            c0, c1 = min(y for _, y in cells), max(y for _, y in cells)
            shape = frozenset((rr-r0, cc-c0) for rr, cc in cells)
            objects[shape] = color

    # Each left panel's zero-cells define the shape to place there.
    starts = [r for r in range(h) if all(grid[r][c] == bg for c in range(left_w))]
    for k in range(len(starts)-1):
        r0, r1 = starts[k] + 1, starts[k+1]
        if r1-r0 != 3:
            continue
        shape = frozenset((r-r0, c-1)
                          for r in range(r0, r1)
                          for c in range(1, left_w-1)
                          if grid[r][c] == 0)
        color = objects.get(shape)
        if color is not None:
            for dr, dc in shape:
                out[r0+dr][1+dc] = color
    return out
